//! Passive optgroup connection preserves actual identity and ownership.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><div id=target>Fallback group<span id=tail>Tail</span></div><select id=select><optgroup id=group label=Group><option value=one>One</option></optgroup></select><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://optgroup-content.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}


#[test]
fn optgroup_content_native_text_replacement_preserves_actual_group_metadata(){let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();let native=format!("{:?}",f.controls[&select].select);run(&mut d,&mut f,&mut p,r#"var target=document.getElementById('target');target.innerHTML='<optgroup label=Group disabled>Old<!--marker--><span>Child</span></optgroup>';var x=target.firstChild,attr=x.getAttributeNode('label'),old=x.firstChild,comment=old.nextSibling,child=x.lastChild,list=x.childNodes,watch=new MutationObserver(function(){});watch.observe(x,{childList:true});x.textContent='A\ud800Z';var records=watch.takeRecords();if(!(x instanceof HTMLOptGroupElement)||x.textContent!=='A\ud800Z'||x.childNodes!==list||list.length!==1||list[0]!==x.firstChild||x.firstChild.nodeType!==3||x.firstChild.ownerDocument!==document||old.parentNode!==null||comment.parentNode!==null||child.parentNode!==null||x.getAttributeNode('label')!==attr||x.label!=='Group'||!x.disabled||records.length!==1||records[0].removedNodes.length!==3||records[0].addedNodes[0]!==x.firstChild||document.getElementById('neighbor').value!=='seed')throw 'actual passive group text replacement';x.textContent='';if(x.firstChild!==null||list.length||x.label!=='Group'||!x.disabled)throw 'actual passive group clear';"#);assert_eq!(format!("{:?}",f.controls[&select].select),native);}
#[test]
fn optgroup_content_native_child_insert_reorder_and_remove_preserve_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.createElement('optgroup'),a=document.createElement('span'),b=document.createElement('span'),target=document.getElementById('target');x.label='Group';x.disabled=true;a.textContent='First';b.textContent='Second';target.appendChild(x);var attr=x.getAttributeNode('label'),list=x.childNodes;x.appendChild(a);x.insertBefore(b,a);if(list.length!==2||list[0]!==b||list[1]!==a||a.parentNode!==x||b.parentNode!==x||x.textContent!=='SecondFirst')throw 'actual passive group children';x.appendChild(b);if(list[0]!==a||list[1]!==b)throw 'real group reorder';if(x.removeChild(a)!==a||a.parentNode!==null||list.length!==1||list[0]!==b||x.getAttributeNode('label')!==attr||x.label!=='Group'||!x.disabled)throw 'real group child removal';");}
#[test]
fn optgroup_content_imported_passive_text_write_keeps_source_isolated(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=new Document(),source=owner.createElementNS('http://www.w3.org/1999/xhtml','optgroup');source.label='Source';source.disabled=true;source.appendChild(owner.createTextNode('Original'));var copy=document.importNode(source,true),text=copy.firstChild,attr=copy.getAttributeNode('label');text.data='A\ud800Z';if(text!==copy.firstChild||text.parentNode!==copy||text.ownerDocument!==document||copy.textContent!=='A\ud800Z'||copy.getAttributeNode('label')!==attr||copy.label!=='Source'||!copy.disabled||source.firstChild.data!=='Original'||source.ownerDocument!==owner||source.firstChild===text)throw 'actual imported group text independence';"#);}

#[test]
fn optgroup_content_resource_refusals_preserve_text_children_and_observers(){
 for data in [false,true]{for mode in 0..5{
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.createElement('optgroup'),target=document.getElementById('target');x.label='Group';x.disabled=true;x.textContent='Old';target.appendChild(x);var old=x.firstChild,attr=x.getAttributeNode('label'),replacement='';for(var n=0;n<500;n++)replacement+='N';var watch=new MutationObserver(function(){});watch.observe(x,{childList:true,characterData:true,subtree:true});");
  // CharacterData replacement allocates no native node.
  if data && mode==3 {continue;}
  p.state.rebuild(&d).unwrap();let tree=format!("{:?}",d.nodes);let before=(p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes(),p.state.attributes.len(),p.state.detached_nodes.clone());let limit=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=0,_=>p.state.execution_deadline=Some(Instant::now())};
  let code=if data{"old.data=replacement;"}else{"x.textContent=replacement;"};let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("{data}/{mode} must refuse"));assert!(error.contains("work")||error.contains("allowance")||error.contains("limit")||error.contains("bound")||error.contains("time"),"{data}/{mode}: {error}");
  assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!((p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes(),p.state.attributes.len(),p.state.detached_nodes.clone()),before);p.state.retained_limit=limit;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();
  run(&mut d,&mut f,&mut p,"if(x.firstChild!==old||old.data!=='Old'||x.getAttributeNode('label')!==attr||x.label!=='Group'||!x.disabled||watch.takeRecords().length)throw 'atomic passive group content refusal';");run(&mut d,&mut f,&mut p,code);run(&mut d,&mut f,&mut p,"if(x.textContent!==replacement||watch.takeRecords().length!==1||x.getAttributeNode('label')!==attr||x.label!=='Group'||!x.disabled)throw 'fresh passive group content recovery';");
  assert!(!p.has_navigation_request());assert!(p.take_dynamic_scripts().is_empty()&&p.take_dynamic_stylesheets().is_empty());assert!(!p.state.images.has_changes());
 }}
}
#[test]
fn optgroup_content_preserves_select_option_resource_and_rich_fragment_guards(){
 let(mut d,mut f,mut p)=fixture();let select=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("select")).unwrap();let native=format!("{:?}",f.controls[&select].select);run(&mut d,&mut f,&mut p,"var inside=document.getElementById('group'),option=inside.firstChild,target=document.getElementById('target');target.innerHTML='<optgroup label=Passive><input id=nested value=seed></optgroup>';var passive=target.firstChild,fresh=document.createElement('optgroup');");
 for code in ["inside.textContent='Wrong';","inside.innerHTML='Wrong';","option.firstChild.data='Wrong';","passive.textContent='Wrong';","fresh.innerHTML='<span>Rich</span>';"]{p.state.rebuild(&d).unwrap();let tree=format!("{:?}",d.nodes);let before=(p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes(),p.state.detached_nodes.clone());p.begin_job();let error=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("native control")||error.contains("cannot remove controls")||error.contains("nonconventional select"),"{code}: {error}");assert_eq!(format!("{:?}",d.nodes),tree);assert_eq!((p.state.retained,p.state.dom_commits,p.state.inert_documents.backing_bytes(),p.state.detached_nodes.clone()),before);assert_eq!(format!("{:?}",f.controls[&select].select),native);}
 p.begin_job();run(&mut d,&mut f,&mut p,"if(inside.parentNode!==document.getElementById('select')||option.textContent!=='One'||document.getElementById('nested').value!=='seed'||passive.parentNode!==target)throw 'actual control content remains';fresh.innerHTML='Plain';if(fresh.textContent!=='Plain')throw 'fresh text-only fragment recovery';");
}
